Lemma bytes_at_u64_read : forall m A zs (k : nat) z,
  bytes_at asegs m A (flat_map le8z zs) -> nth_error zs k = Some z ->
  ov_read_bytes asegs m (Z_to_bv 64 (A + 8 * Z.of_nat k)) 8 = Some (le8 (wz z)).
Proof.
  intros m A zs k z B N. rewrite flat_map_le8z_u64s in B.
  assert (N' : nth_error (map wz zs) k = Some (wz z)) by (rewrite nth_error_map, N; reflexivity).
  destruct (u64s_split _ _ _ N') as (pre & post & E & Hlen & Eu & Hlu).
  replace (Z_to_bv 64 (A + 8 * Z.of_nat k)) with (wa (A + Z.of_nat (8 * k))) by (symmetry; apply wa_of_Z_to_bv; lia).
  rewrite (bytes_at_ov_read asegs m A _ (8 * k) 8 B).
  2:{ rewrite Eu, !length_app, length_le8, Hlu. lia. }
  rewrite Eu, skipn_app, skipn_all2, Hlu, Nat.sub_diag by lia. rewrite skipn_O, app_nil_l.
  rewrite firstn_app, firstn_all2 by (rewrite length_le8; lia).
  rewrite length_le8, Nat.sub_diag, firstn_O, app_nil_r. reflexivity.
Qed.

Lemma FT_tab_reads : forall m (i : Z), rw_cells asegs m AG_FIELD_TABLE FTCells -> 0 <= i < 130 ->
  ov_read_bytes asegs m (Z_to_bv 64 (AG_FIELD_TABLE + 16 * i)) 8 = Some (le8 (wz (ft_ptr (Z.to_nat i))))
  /\ ov_read_bytes asegs m (Z_to_bv 64 (AG_FIELD_TABLE + 16 * i + 8)) 8 = Some (le8 (wz (ft_len (Z.to_nat i)))).
Proof.
  intros m i C Hi. pose proof (rw_cells_bytes_at _ _ _ _ C) as B. unfold FTCells in B. cbn [cells_bytes cbytes] in B.
  apply bytes_at_app in B. destruct B as [B _]. unfold FT_TAB_BYTES in B.
  destruct (nth_error FT_BYNAME (Z.to_nat i)) as [pl|] eqn:N.
  2:{ exfalso. apply nth_error_None in N. rewrite FT_BYNAME_length in N. lia. }
  destruct (ft_words_nth FT_BYNAME (Z.to_nat i) pl N) as [N1 N2]. fold ft_words in N1, N2.
  unfold ft_ptr, ft_len. rewrite (nth_error_nth _ _ _ N). split.
  - replace (AG_FIELD_TABLE + 16 * i) with (AG_FIELD_TABLE + 8 * Z.of_nat (2 * Z.to_nat i)) by lia.
    exact (bytes_at_u64_read _ _ _ _ _ B N1).
  - replace (AG_FIELD_TABLE + 16 * i + 8) with (AG_FIELD_TABLE + 8 * Z.of_nat (2 * Z.to_nat i + 1)) by lia.
    exact (bytes_at_u64_read _ _ _ _ _ B N2).
Qed.

Lemma FT_map_read : forall m (j : Z), rw_cells asegs m AG_FIELD_TABLE FTCells -> 0 <= j < 1367 ->
  ov_read_bytes asegs m (Z_to_bv 64 (AG_FIELD_TABLE + 2080 + j)) 1 = Some [b8 (nth (Z.to_nat j) FT_MAP 0)].
Proof.
  intros m j C Hj. pose proof (rw_cells_bytes_at _ _ _ _ C) as B. unfold FTCells in B. cbn [cells_bytes cbytes] in B.
  apply bytes_at_app in B. destruct B as [_ B]. apply bytes_at_app in B. destruct B as [B _].
  rewrite FT_TAB_BYTES_length in B. change (Z.of_nat 2080) with 2080 in B.
  destruct (nth_error FT_MAP (Z.to_nat j)) as [v|] eqn:N.
  2:{ exfalso. apply nth_error_None in N. rewrite FT_MAP_length in N. lia. }
  apply (u8ro_read asegs m (AG_FIELD_TABLE + 2080) FT_MAP_BYTES j); [exact B | | lia | symmetry; apply wa_of_Z_to_bv; unfold AG_FIELD_TABLE; lia].
  unfold FT_MAP_BYTES. rewrite (nth_error_map b8 (Z.to_nat j) FT_MAP), N. cbn [option_map].
  rewrite (nth_error_nth _ _ _ N). reflexivity.
Qed.

(* [comment removed for export] *)
Lemma FT_shadow0 : forall m x, ACONST m -> AG_FIELD_TABLE <= x < AG_FIELD_TABLE + 3456 ->
  ov_read_bytes asegs m (Z_to_bv 64 (Z.shiftr x 3 + 2147450880)) 1 = Some [b8 0].
Proof.
  intros m x AC Hx. apply (accessible_read0_in m AG_FIELD_TABLE 3456 x (ft_tab_accessible m AC)); [reflexivity | reflexivity | exact Hx].
Qed.

