Definition AS2F_STACK : Z := 48 + AEQ_STACK.

Definition s2f_post_v (v : Z) (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P lo : Z) (bs : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz v) a1 a2 a3 a4 a5 a6 a7
                  s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ munch [(lo, bv_unsigned sp)]%Z m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ stk asegs m' lo (bv_unsigned sp)
    /\ bytes_at asegs m' P bs /\ FT m'
    /\ ACONST m' /\ accessible m' P (Z.of_nat (length bs)).

Definition s2f_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P lo : Z) (bs : list byte) (m : mem) : machine_state -> Prop :=
  s2f_post_v (ft_lookup (zbytes bs)) ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P lo bs m.

(* [comment removed for export] *)
Definition s2f_stmt : Prop :=
  forall ra sp gp tp t0 t1 t2 s0 s1 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (P lo : Z) (bs : list byte),
  bytes_at asegs m P bs -> FT m -> P + Z.of_nat (length bs) < 2^64 ->
  stk asegs m lo (bv_unsigned sp) -> lo + AS2F_STACK <= bv_unsigned sp -> aceil <= lo ->
  (bv_unsigned sp <= P \/ P + Z.of_nat (length bs) <= lo) ->
  mem_inv asegs m ->
  (* [comment removed for export] *)
  ACONST m -> accessible m P (Z.of_nat (length bs)) ->
  evt asegs (s2f_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P lo bs m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz AG_FIELD_TABLE) (wz P) (wz (Z.of_nat (length bs))) a3 a4 a5 a6 a7
              s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_STRING_TO_FIELD) fc None m (seg_rom asegs)).

Definition s2_ctx (m m1 : mem) (sp s0v s1v s2v s3v s4v rav : word) (P lo : Z) (bs : list byte) : Prop :=
  rw_cells asegs m1 (bv_unsigned sp + -48) [C8 s4v; C8 s3v; C8 s2v; C8 s1v; C8 s0v; C8 rav]
  /\ bytes_at asegs m1 P bs
  /\ rw_cells asegs m1 AG_FIELD_TABLE FTCells /\ rw_cells asegs m1 AG_FIELD_TABLE_GUARD FTGuardCells
  /\ stk asegs m1 lo (bv_unsigned sp + -48)
  /\ munch [(lo, bv_unsigned sp)]%Z m m1 /\ wmono asegs m m1 /\ mem_inv asegs m1
  /\ dg_side m P (Z.of_nat (length bs)).

Definition s2_pure (sp : word) (P lo : Z) (bs : list byte) : Prop :=
  P + Z.of_nat (length bs) < 2^64 /\ lo + AS2F_STACK <= bv_unsigned sp /\ aceil <= lo
  /\ (bv_unsigned sp <= P \/ P + Z.of_nat (length bs) <= lo).

End S2F.

Ltac s2_open CTX PURE :=
  destruct CTX as (FR & WIN & C1 & C2 & ST & MU & WM & MI & SD);
  destruct PURE as (WEND & LO & CEIL & SEPS);
  pose proof (bytes_at_bound _ _ _ _ WIN) as WB;
  pose proof aceil_facts as (AF1 & _);
  hydeL SEPS;
  unfold FTCells in C1; unfold FTGuardCells in C2;
  unfold AS2F_STACK, AEQ_STACK in *.

